"use client";

export type { CommandModalHandler } from "@easy-shadcn/command-modal";
export type { AlertModalProps } from "./alert-modal";
export type { ModalProps } from "./modal";

import CommandModal from "@easy-shadcn/command-modal";
import { AlertModal as OriginalAlertModal } from "./alert-modal";
import AlertCommandModal from "./alert-modal-helper";
import { Modal as OriginalModal } from "./modal";

// Only the public command-modal surface rides on the Modal namespace —
// internals like the reducer and contexts stay in the package.
const commandModalApi = {
  create: CommandModal.create,
  hide: CommandModal.hide,
  Provider: CommandModal.Provider,
  register: CommandModal.register,
  remove: CommandModal.remove,
  show: CommandModal.show,
  unregister: CommandModal.unregister,
  useModal: CommandModal.useModal,
  useModalHolder: CommandModal.useModalHolder,
};

export const AlertModal: typeof OriginalAlertModal & typeof AlertCommandModal =
  Object.assign(OriginalAlertModal, AlertCommandModal);

export const Modal: typeof OriginalModal & typeof commandModalApi =
  Object.assign(OriginalModal, commandModalApi);

"use client";

import type { ClassValue } from "class-variance-authority/types";
import type React from "react";
import {
  type ComponentProps,
  type ReactElement,
  type ReactNode,
  useState,
} from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { cn } from "@/lib/utils";
import { AsyncButton } from "../async-button";

type ModalActionProps = Omit<
  ComponentProps<typeof AsyncButton>,
  "children" | "dangerouslySetInnerHTML" | "onClick"
>;

const getSafeActionProps = (
  props: ModalActionProps | undefined
): ModalActionProps => {
  const {
    children: _ignoredChildren,
    dangerouslySetInnerHTML: _ignoredDangerouslySetInnerHTML,
    onClick: _ignoredOnClick,
    ...safeProps
  } = (props ?? {}) as ComponentProps<typeof AsyncButton>;

  return safeProps;
};

export interface ModalProps {
  /**
   * Extra props for the default footer's cancel AsyncButton. The label, raw
   * HTML, and click handler are Compose-owned; use cancelText and onCancel.
   */
  cancelProps?: ModalActionProps;
  cancelText?: ReactNode;
  children?: ReactNode;
  className?: ClassValue;
  /**
   * Extra props for the default footer's confirm AsyncButton. The label, raw
   * HTML, and click handler are Compose-owned; use confirmText and onConfirm.
   */
  confirmProps?: ModalActionProps;
  confirmText?: ReactNode;
  contentClassName?: ClassValue;
  defaultOpen?: boolean;
  description?: ReactNode;
  descriptionClassName?: ClassValue;
  /** Prevents closing via outside clicks. Forwarded to the Base UI Dialog. */
  disablePointerDismissal?: boolean;
  /** Overrides the default confirm/cancel footer entirely. */
  footer?: ReactNode;
  footerClassName?: ClassValue;
  headerClassName?: ClassValue;
  /**
   * Called when the cancel button is pressed. May return a Promise — the
   * button shows a pending state and the modal stays open until it resolves;
   * a rejection keeps the modal open.
   */
  onCancel?: () => void | Promise<void>;
  /**
   * Called when the confirm button is pressed. May return a Promise — the
   * button shows a pending state and the modal stays open until it resolves;
   * a rejection keeps the modal open.
   */
  onConfirm?: () => void | Promise<void>;
  onOpenChange?: (open: boolean) => void;
  /**
   * Base UI Dialog's post-transition hook — fires after the open/close
   * animation completes (with the resulting `open` state). Forwarded straight
   * to the underlying Dialog. command-modal's adapter wires teardown here.
   */
  onOpenChangeComplete?: (open: boolean) => void;
  open?: boolean;
  showCloseButton?: boolean;
  title?: ReactNode;
  titleClassName?: ClassValue;
  trigger?: ReactElement;
}

export const Modal: React.FC<ModalProps> = ({
  open,
  defaultOpen,
  onOpenChange,
  title,
  titleClassName,
  description,
  descriptionClassName,
  children,
  contentClassName,
  className,
  disablePointerDismissal,
  footer,
  footerClassName,
  headerClassName,
  cancelProps,
  cancelText,
  onCancel,
  confirmProps,
  confirmText,
  onConfirm,
  trigger,
  showCloseButton = true,
  onOpenChangeComplete,
}) => {
  const [internalOpen, setInternalOpen] = useState(defaultOpen ?? false);
  const currentOpen = open === undefined ? internalOpen : open;

  const handleOpenChange = (next: boolean) => {
    if (open === undefined) {
      setInternalOpen(next);
    }
    onOpenChange?.(next);
  };

  const close = () => handleOpenChange(false);

  // The flat confirm/cancel footer only appears when asked for; a rejected
  // async handler skips close() (AsyncButton catches it), keeping the modal
  // open on errors.
  const hasDefaultFooter =
    onConfirm !== undefined ||
    onCancel !== undefined ||
    confirmText !== undefined ||
    cancelText !== undefined ||
    confirmProps !== undefined ||
    cancelProps !== undefined;
  const safeCancelProps = getSafeActionProps(cancelProps);
  const safeConfirmProps = getSafeActionProps(confirmProps);
  const footerNode =
    footer ??
    (hasDefaultFooter ? (
      <>
        <AsyncButton
          {...safeCancelProps}
          onClick={async () => {
            await onCancel?.();
            close();
          }}
          variant={safeCancelProps.variant ?? "outline"}
        >
          {cancelText ?? "Cancel"}
        </AsyncButton>
        <AsyncButton
          {...safeConfirmProps}
          onClick={async () => {
            await onConfirm?.();
            close();
          }}
        >
          {confirmText ?? "OK"}
        </AsyncButton>
      </>
    ) : null);

  return (
    <Dialog
      disablePointerDismissal={disablePointerDismissal}
      onOpenChange={handleOpenChange}
      onOpenChangeComplete={onOpenChangeComplete}
      open={currentOpen}
    >
      {trigger && <DialogTrigger render={trigger} />}
      <DialogContent
        className={cn(className)}
        showCloseButton={showCloseButton}
      >
        {(title || description) && (
          <DialogHeader className={cn(headerClassName)}>
            {title && (
              <DialogTitle className={cn(titleClassName)}>{title}</DialogTitle>
            )}
            {description && (
              <DialogDescription
                className={cn(descriptionClassName)}
                render={<div />}
              >
                {description}
              </DialogDescription>
            )}
          </DialogHeader>
        )}
        {children && (
          <div className={cn("text-sm", contentClassName)}>{children}</div>
        )}
        {footerNode && (
          <DialogFooter className={cn(footerClassName)}>
            {footerNode}
          </DialogFooter>
        )}
      </DialogContent>
    </Dialog>
  );
};

"use client";

import type { ClassValue } from "class-variance-authority/types";
import type React from "react";
import {
  type ComponentProps,
  type ReactElement,
  type ReactNode,
  useState,
} from "react";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { cn } from "@/lib/utils";
import { AsyncButton } from "../async-button";

type AlertModalActionProps = Omit<
  ComponentProps<typeof AsyncButton>,
  "children" | "dangerouslySetInnerHTML" | "onClick"
>;

const getSafeActionProps = (
  props: AlertModalActionProps | undefined
): AlertModalActionProps => {
  const {
    children: _ignoredChildren,
    dangerouslySetInnerHTML: _ignoredDangerouslySetInnerHTML,
    onClick: _ignoredOnClick,
    ...safeProps
  } = (props ?? {}) as ComponentProps<typeof AsyncButton>;

  return safeProps;
};

export interface AlertModalProps {
  /**
   * Extra props for the cancel AsyncButton. The label, raw HTML, and click
   * handler are Compose-owned; use cancelText and onCancel.
   */
  cancelProps?: AlertModalActionProps;
  cancelText?: ReactNode;
  className?: ClassValue;
  /**
   * Extra props for the confirm AsyncButton. The label, raw HTML, and click
   * handler are Compose-owned; use confirmText and onConfirm.
   */
  confirmProps?: AlertModalActionProps;
  confirmText?: ReactNode;
  defaultOpen?: boolean;
  description?: ReactNode;
  descriptionClassName?: ClassValue;
  /** Overrides the default confirm/cancel footer entirely. */
  footer?: ReactNode;
  footerClassName?: ClassValue;
  headerClassName?: ClassValue;
  /**
   * Called when the cancel button is pressed. May return a Promise — the
   * button shows a pending state and the modal stays open until it resolves;
   * a rejection keeps the modal open.
   */
  onCancel?: () => void | Promise<void>;
  /**
   * Called when the confirm button is pressed. May return a Promise — the
   * button shows a pending state and the modal stays open until it resolves;
   * a rejection keeps the modal open.
   */
  onConfirm?: () => void | Promise<void>;
  onOpenChange?: (open: boolean) => void;
  /**
   * Base UI AlertDialog's post-transition hook — fires after the open/close
   * animation completes (with the resulting `open` state). Forwarded straight
   * to the underlying AlertDialog. command-modal's adapter wires teardown here.
   */
  onOpenChangeComplete?: (open: boolean) => void;
  open?: boolean;
  /** Hide the cancel button for single-action alerts. @default true */
  showCancel?: boolean;
  /** Forwarded to the AlertDialogContent primitive. */
  size?: "default" | "sm";
  title?: ReactNode;
  titleClassName?: ClassValue;
  trigger?: ReactElement;
}

export const AlertModal: React.FC<AlertModalProps> = ({
  open,
  defaultOpen,
  onOpenChange,
  title,
  titleClassName,
  description,
  descriptionClassName,
  className,
  headerClassName,
  size,
  trigger,
  footer,
  footerClassName,
  cancelText,
  onCancel,
  cancelProps,
  confirmText,
  onConfirm,
  confirmProps,
  showCancel = true,
  onOpenChangeComplete,
}) => {
  const [internalOpen, setInternalOpen] = useState(defaultOpen ?? false);
  const currentOpen = open === undefined ? internalOpen : open;

  const handleOpenChange = (next: boolean) => {
    if (open === undefined) {
      setInternalOpen(next);
    }
    onOpenChange?.(next);
  };

  const close = () => handleOpenChange(false);
  const safeCancelProps = getSafeActionProps(cancelProps);
  const safeConfirmProps = getSafeActionProps(confirmProps);

  return (
    <AlertDialog
      onOpenChange={handleOpenChange}
      onOpenChangeComplete={onOpenChangeComplete}
      open={currentOpen}
    >
      {trigger && <AlertDialogTrigger render={trigger} />}
      <AlertDialogContent className={cn(className)} size={size}>
        {(title || description) && (
          <AlertDialogHeader className={cn(headerClassName)}>
            {title && (
              <AlertDialogTitle className={cn(titleClassName)}>
                {title}
              </AlertDialogTitle>
            )}
            {description && (
              <AlertDialogDescription
                className={cn(descriptionClassName)}
                render={<div />}
              >
                {description}
              </AlertDialogDescription>
            )}
          </AlertDialogHeader>
        )}
        <AlertDialogFooter className={cn(footerClassName)}>
          {footer ?? (
            <>
              {showCancel && (
                <AsyncButton
                  {...safeCancelProps}
                  onClick={async () => {
                    await onCancel?.();
                    close();
                  }}
                  variant={safeCancelProps.variant ?? "outline"}
                >
                  {cancelText ?? "Cancel"}
                </AsyncButton>
              )}
              <AsyncButton
                {...safeConfirmProps}
                onClick={async () => {
                  await onConfirm?.();
                  close();
                }}
              >
                {confirmText ?? "OK"}
              </AsyncButton>
            </>
          )}
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
};

"use client";

import CommandModal from "@easy-shadcn/command-modal";
import { AlertModal, type AlertModalProps } from "./alert-modal";

type AlertHelperProps = Omit<AlertModalProps, "open" | "onOpenChange">;

type CloseCompleteHook = ((open: boolean) => void) | undefined;

/**
 * Compose the caller's and command-modal's `onOpenChangeComplete` hooks, then
 * unregister the one-shot modal once it has fully closed. Each helper call
 * creates a fresh component — without this, long-lived apps leak one registry
 * entry per call.
 */
const chainCloseAndUnregister =
  (id: string, callerHook: CloseCompleteHook, modalHook: CloseCompleteHook) =>
  (open: boolean) => {
    callerHook?.(open);
    modalHook?.(open);
    if (!open) {
      CommandModal.unregister(id);
    }
  };

/**
 * Promise-style alert: a single OK button.
 * Resolves once the user confirms or dismisses the dialog.
 */
const alert = (
  props: Omit<
    AlertHelperProps,
    // A custom footer would disconnect the promise from the OK button.
    "cancelProps" | "cancelText" | "footer" | "onCancel" | "showCancel"
  >
): Promise<void> => {
  const AlertCommandModal = CommandModal.create(() => {
    const { id, modalProps, resolve } = CommandModal.useModal();
    return (
      <AlertModal
        {...props}
        {...modalProps}
        onConfirm={async () => {
          await props.onConfirm?.();
          resolve(true);
        }}
        onOpenChangeComplete={chainCloseAndUnregister(
          id,
          props.onOpenChangeComplete,
          modalProps.onOpenChangeComplete
        )}
        showCancel={false}
      />
    );
  });

  return CommandModal.show(AlertCommandModal).then(() => {
    // Dismissal and confirmation both settle the alert; there is nothing to
    // distinguish for a single-button dialog.
    return;
  });
};

/**
 * Promise-style confirm. Resolves `true` when confirmed, `false` when
 * cancelled or dismissed (Escape) — it never rejects.
 */
const confirm = (
  props: Omit<AlertHelperProps, "footer">
): Promise<boolean> => {
  const AlertCommandModal = CommandModal.create(() => {
    const { id, modalProps, resolve } = CommandModal.useModal();

    return (
      <AlertModal
        {...props}
        {...modalProps}
        onCancel={async () => {
          await props.onCancel?.();
          resolve(false);
        }}
        onConfirm={async () => {
          await props.onConfirm?.();
          resolve(true);
        }}
        onOpenChangeComplete={chainCloseAndUnregister(
          id,
          props.onOpenChangeComplete,
          modalProps.onOpenChangeComplete
        )}
      />
    );
  });

  return CommandModal.show(AlertCommandModal).then((value) => value === true);
};

export default {
  alert,
  confirm,
};
